"""Displays the content of the given directory.  Default value is the current directory.

    Examples:
        >>> os_ls()\n
        ['temp.py', 'worksheet.py']

        >>> os_ls('../..')\n
        ['ps1_files', 'sec_ops', 'pyplay', 'bashplay']
    """
def os_ls(thepath: Any = ".") -> object {
    import os;
    return os.listdir(thepath);
}

test_blocks:
test "t0" {
    assert (os_ls() == os_ls("."));;
}

test "t1" {
    assert (os_ls("../..") == os_ls("../.."));;
}

test "t2" {
    assert (os_ls(".") == os_ls());;
}

test "t3" {
    assert (os_ls("../..") == os_ls("../../"));;
}
